#!/usr/bin/env python3
"""Capture a real seekdb read/write record for the Dify track (route B).

Runs against a real seekdb kernel and writes ``Dify/EVIDENCE_ROOT.json``:
  * the DDL actually executed,
  * rows written (knowledge base chunks + review log rows),
  * the hybrid retrieval plan generated by seekdb (fulltext + vector branches),
  * the hits returned,
  * the review-log rows written back.

    python Dify/seekdb_service/capture_evidence.py
"""

from __future__ import annotations

import json
import sys
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from embedder import Embedder  # noqa: E402
from seekdb_store import CREATE_TABLE, CREATE_REVIEW_TABLE, SeekdbStore  # noqa: E402
from serve import ingest, load_kb_documents  # noqa: E402

QUERIES = [
    "HNSW 向量索引的建表语句是什么？",
    "混合检索的 RRF 融合是怎么做的？",
    "深分页 OFFSET 太大怎么办？",
    "端侧 INT8 量化会损失多少召回率？",
]


def main() -> int:
    sys.stdout.reconfigure(encoding="utf-8")
    base = HERE.parent
    # a dedicated data dir so this never collides with a running service
    store = SeekdbStore(str(HERE / ".data" / "evidence-seekdb"))
    store.open(reset=True)
    embedder = Embedder.get()

    evidence: dict[str, object] = {
        "engine": "seekdb",
        "mode": store.mode,
        "embedding": {
            "model": "bge-small-zh-v1.5 (INT8 ONNX)" if not embedder.is_fallback else "deterministic hashing fallback",
            "dim": 512,
            "fallback": bool(embedder.is_fallback),
        },
        "ddl": {
            "knowledge_base": " ".join(CREATE_TABLE.split()),
            "review_log": " ".join(CREATE_REVIEW_TABLE.split()),
        },
        "writes": {},
        "retrievals": [],
    }

    started = time.time()
    chunks = ingest(store, embedder, load_kb_documents())
    evidence["writes"] = {"knowledge_chunks": chunks, "rows_in_table": store.count(), "seconds": round(time.time() - started, 1)}

    # write a review round back (application data storage)
    review_id = store.write_review(
        engine="dify-smoke",
        sql_text="SELECT * FROM orders LIMIT 20, 200000;",
        findings=[{"level": "warn", "id": "OB-007", "title": "深分页 OFFSET"}],
        summary="真实写入验证：1 条警告",
        kb_hits=chunks,
    )
    evidence["writes"]["review_log_rows"] = store.review_count()
    evidence["writes"]["review_log_id"] = review_id

    for query in QUERIES:
        vector = embedder.embed_one(query)
        parm = {
            "query": {"query_string": {"fields": ["document"], "query": query}},
            "knn": {"field": "embedding", "k": 12, "query_vector": vector},
            "rank": {"rrf": {}},
            "size": 3,
        }
        plan = store._hybrid_sql(parm)
        hits = store.search(query, vector, 3, "hybrid")
        evidence["retrievals"].append(
            {
                "query": query,
                "plan_has_fulltext_branch": "_fts" in plan,
                "plan_has_vector_branch": "_vs" in plan,
                "plan_head": " ".join(plan.split())[:220],
                "hits": [
                    {"title": hit["title"], "source": hit["source"], "score": hit["score"], "snippet": hit["text"][:120]}
                    for hit in hits
                ],
            }
        )

    store.close()

    out = base / "EVIDENCE_ROOT.json"
    out.write_text(json.dumps(evidence, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"evidence written to {out}")
    print(f"knowledge chunks: {chunks}, review rows: {evidence['writes']['review_log_rows']}")
    for item in evidence["retrievals"]:
        print(f"  {item['query']} -> {len(item['hits'])} hits "
              f"(fulltext={item['plan_has_fulltext_branch']}, vector={item['plan_has_vector_branch']})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
